 metrics=[dict(metric=k,value=v) for k,v in [('Predictors',main['predictors']),('LP calls',main['linear_programs']),('New nonlinear trial paths',main['nonlinear_trial_paths']),('Finite joint maps',main['finite_maps']),('Accepted paths',main['accepted_steps']),('Stop',main['stop']),('Initial complete lift passed',main['initial_lift_pass']),('Final differs from original 440',main['new_final_differs_from_source']),('Final hard rows pass',main['final']['hard_pass']),('Final f/p phase order passes',main['final']['monotone_phase_pass']),('All buffered inequalities pass',main['final']['all_inequalities_pass']),('Final soft violation',main['final']['soft_merit']),('Full original control-bound margin',main['final']['coordinate_bound_minimum']),('Total normal residual',float(abs(final['equalities'][:-1]).max())),('Normalized hover residual',float(abs(final['equalities'][-1]))),('Sampled geometry passes',audit['sampled_geometry_passed']),('Housing minimum (m)',audit['minimum_housing_m']),('CoP minimum (m)',audit['minimum_cop_m']),('Moving command margin (rad)',audit['minimum_moving_command_margin_rad']),('All37 command margin, fixed fingers included (rad)',audit['minimum_command_margin_rad']),('Original ideal-clock rate (rad/tick)',audit['original_clock_rate_minimum']),('Original ideal-clock target (rad)',audit['original_clock_target_minimum']),('New finite-work columns',audit['new_finite_work_columns']),('Exact441 inherited records',audit['inherited441_exact_records']),('Duplicate new records',audit['duplicate_new_records'])]]
